    function orderById(id){return orders.find(function(item){return item.id===id})}
    function tone(value){if(['正常','通讯正常','在线','充电中','已完成','生效中','进行中','启用','已到账','已入账','已退款','发送成功','无退款','发放中'].indexOf(value)!==-1)return 'good';if(['部分中断','待审批','待处理','处理中','待支付','待生效','余额预警','即将用尽','维护中','未激活','未接入','待开始','已提交退费'].indexOf(value)!==-1)return 'warn';if(['通讯异常','异常','离线','下线','故障','发送失败','已禁用'].indexOf(value)!==-1)return 'bad';return 'blue'}
