    function filterConfig(){var common=[{key:'operator',label:'所属运营商',options:operators,placeholder:'全部运营商'},{key:'station',label:'所属场站',options:stations.map(function(item){return {value:item.id,label:item.name}}),placeholder:'全部场站'}];if(state.page==='场站管理')return [{key:'operator',label:'所属运营商',options:operators,placeholder:'全部运营商'},{key:'status',label:'运行状态',options:['正常','维护中','下线','建设中'],placeholder:'全部运行状态'},{key:'communication',label:'通讯状态',options:[{value:'正常',label:'通讯正常'},{value:'异常',label:'部分中断'},{value:'未接入',label:'通讯异常'}],placeholder:'全部通讯状态'},{key:'type',label:'站点类型',options:['公共','个人','公交（专用）','其他'],placeholder:'全部站点类型'},{key:'facility',label:'场地类型',options:Array.from(new Set(stations.map(function(item){return item.facility}))),placeholder:'全部场地类型'},{key:'region',label:'所属区域',type:'region'},{key:'plan',label:'收费方案',options:plans.map(function(item){return item.name}),placeholder:'全部收费方案'},{key:'created',label:'创建时间',type:'dateRange'}];if(state.page==='充电桩管理')return common.concat([{key:'status',label:'设备状态',options:['在线','离线','未激活'],placeholder:'全部状态'},{key:'type',label:'设备类型',options:['直流','交流'],placeholder:'全部类型'}]);if(state.page==='充电枪管理')return common.concat([{key:'status',label:'枪状态',options:['充电中','空闲','故障','离线'],placeholder:'全部状态'},{key:'type',label:'枪类型',options:['快充','慢充'],placeholder:'全部类型'}]);if(state.page==='充电订单')return common.concat([{key:'status',label:'订单状态',options:['充电中','待支付','已完成'],placeholder:'全部状态'},{key:'payment',label:'支付方式',options:['钱包支付','即充即付'],placeholder:'全部支付方式'},{key:'abnormal',label:'异常情况',options:[{value:'yes',label:'异常订单'},{value:'no',label:'正常订单'}],placeholder:'全部订单'}]);if(state.page==='活动投放')return common.concat([{key:'status',label:'活动状态',options:['进行中','待开始','已结束'],placeholder:'全部状态'},{key:'template',label:'活动模板',options:templates.map(function(item){return item.name}),placeholder:'全部模板'}]);if(state.page==='收支明细')return [{key:'operator',label:'所属运营商',options:operators,placeholder:'全部运营商'},{key:'direction',label:'收支类型',options:['收入','支出','内部划转'],placeholder:'全部收支'},{key:'billType',label:'账单类型',options:['充电订单','钱包充值','钱包消费','订单退款','企业充值'],placeholder:'全部账单'},{key:'date',label:'账单日期',type:'date'}];if(state.page==='对账管理')return [{key:'operator',label:'所属运营商',options:operators,placeholder:'全部运营商'},{key:'station',label:'所属场站',options:stations.map(function(item){return {value:item.id,label:item.name}}),placeholder:'全部场站'},{key:'date',label:'订单日期',type:'date'}];if(state.page==='退款审批')return common.concat([{key:'status',label:'审批状态',options:['待审批','已退款','已驳回'],placeholder:'全部状态'}]);return common.concat([{key:'status',label:'业务状态',options:['正常','启用','进行中','已完成'],placeholder:'全部状态'}])}
    function stationRegionParts(station){return String(station.region||'').split('/').map(function(item){return item.trim()})}
    function regionFilterControl(){var province=state.filters.province||'',city=state.filters.city||'',district=state.filters.district||'',provinces=Array.from(new Set(stations.map(function(item){return stationRegionParts(item)[0]}))),cities=Array.from(new Set(stations.filter(function(item){return !province||stationRegionParts(item)[0]===province}).map(function(item){return stationRegionParts(item)[1]}))),districts=Array.from(new Set(stations.filter(function(item){var parts=stationRegionParts(item);return (!province||parts[0]===province)&&(!city||parts[1]===city)}).map(function(item){return stationRegionParts(item)[2]})));return '<div class="filter-region"><select class="select" id="filterProvince" data-region-level="province" data-filter="province">'+optionList(provinces,province,'选择省')+'</select><select class="select" id="filterCity" data-region-level="city" data-filter="city">'+optionList(cities,city,'选择市')+'</select><select class="select" id="filterDistrict" data-region-level="district" data-filter="district">'+optionList(districts,district,'选择区')+'</select></div>'}
    function filterControl(field){if(field.type==='date')return '<input class="input" type="date" data-filter="'+field.key+'" value="'+esc(state.filters[field.key]||'')+'">';if(field.type==='dateRange')return '<div class="filter-range"><input class="input" type="date" data-filter="createdStart" value="'+esc(state.filters.createdStart||'')+'" aria-label="创建开始时间"><span>—</span><input class="input" type="date" data-filter="createdEnd" value="'+esc(state.filters.createdEnd||'')+'" aria-label="创建结束时间"></div>';if(field.type==='region')return regionFilterControl();return '<select class="select" data-filter="'+field.key+'">'+optionList(field.options,state.filters[field.key],field.placeholder)+'</select>'}
    function querybar(placeholder){var config=filterConfig(),active=Object.keys(state.filters).filter(function(key){return !!state.filters[key]}).length;return '<div class="querybar"><div class="search-box"><input class="input" id="keyword" value="'+esc(state.keyword)+'" placeholder="'+esc(placeholder||'搜索名称、编号或手机号')+'"></div><div class="filter-wrap"><button class="btn icon-btn" data-action="toggle-filter" aria-label="筛选选项">⚑'+(active?'<span class="filter-badge">'+active+'</span>':'')+'</button><div class="filter-popover hidden" id="filterPopover"><div class="filter-title">筛选选项</div><div class="filter-grid">'+config.map(function(field){return '<div><label class="field-label">'+esc(field.label)+'</label>'+filterControl(field)+'</div>'}).join('')+'</div><div class="filter-actions"><button class="btn" data-action="reset-filters">重置</button><button class="btn btn-primary" data-action="apply-filters">筛选</button></div></div></div><button class="btn btn-primary" data-action="query">查询</button></div>'}
    function toolbar(title,count,actions){return '<div class="toolbar"><div class="toolbar-title">'+esc(title)+'<span>共 '+count+' 条</span></div><div class="toolbar-actions">'+actions+'</div></div>'}
    function pagination(total){var pages=Math.max(1,Math.ceil(total/state.pageSize));return '<div class="pagination"><span>共 '+total+' 条</span><div class="pager"><select class="select page-size" id="pageSize">'+optionList([10,20,50,100],state.pageSize)+'</select><button class="page-btn" data-action="page-prev">‹</button><button class="page-btn current">'+state.pageNo+'</button><button class="page-btn" data-action="page-next" data-max="'+pages+'">›</button></div></div>'}
    function rowsPage(records){state.pageNo=Math.min(state.pageNo,Math.max(1,Math.ceil(records.length/state.pageSize)));return records.slice((state.pageNo-1)*state.pageSize,state.pageNo*state.pageSize)}
    function match(record){var query=state.keyword.trim().toLowerCase();if(query&&JSON.stringify(record).toLowerCase().indexOf(query)===-1)return false;return Object.keys(state.filters).every(function(key){var expected=state.filters[key];if(!expected)return true;if(key==='station')return record.stationId===expected||(record.stationIds||[]).indexOf(expected)!==-1;if(key==='abnormal')return expected==='yes'?!!record.abnormal:!record.abnormal;if(key==='benefit'){var offer=Number(record.offer||0),benefitType=record.benefitType||record.discountType||'';if(expected==='未参与优惠')return offer<=0&&benefitType.indexOf('会员')===-1&&benefitType.indexOf('券')===-1;if(expected==='优惠券优惠')return (offer>0&&benefitType.indexOf('券')!==-1)||benefitType==='优惠券';if(expected==='会员卡优惠')return benefitType.indexOf('会员')!==-1;return true}if(key==='date')return String(record.created||record.time||record.date||'').slice(0,10)===expected;if(key==='province'||key==='city'||key==='district'){var parts=stationRegionParts(record),index={province:0,city:1,district:2}[key];return parts[index]===expected}if(key==='createdStart')return String(record.created||'').slice(0,10)>=expected;if(key==='createdEnd')return String(record.created||'').slice(0,10)<=expected;return String(record[key]||'')===expected})}
    function renderTable(columns,records,rowBuilder){var shown=rowsPage(records),body=shown.length?shown.map(rowBuilder).join(''):'<tr><td colspan="'+(columns.length+1)+'"><div class="placeholder"><div><div class="placeholder-icon">⌕</div><h3>暂无匹配数据</h3><p>请调整关键词或筛选条件</p></div></div></td></tr>';return '<div class="table-wrap"><table class="table"><thead><tr>'+columns.map(function(column){return '<th>'+column+'</th>'}).join('')+'<th class="actions">操作</th></tr></thead><tbody>'+body+'</tbody></table></div>'+pagination(records.length)}
    function actionButton(kind,id){return '<button class="more" data-action="open-menu" data-kind="'+kind+'" data-id="'+esc(id)+'" aria-label="操作菜单">···</button>'}
    function showToast(message){var box=$('toast');box.textContent=message;box.classList.remove('hidden');clearTimeout(showToast.timer);showToast.timer=setTimeout(function(){box.classList.add('hidden')},2200)}
    function buildNavigation(){$('navigation').innerHTML=navigation.map(function(section){return '<div><div class="nav-title">'+esc(section.group)+'</div>'+section.items.map(function(item){return '<button class="nav-link '+(state.page===item[0]?'active':'')+'" data-nav="'+esc(item[0])+'" data-group="'+esc(section.group)+'"><span class="nav-icon">'+item[1]+'</span>'+esc(item[0])+'</button>'}).join('')+'</div>'}).join('');$('crumbGroup').textContent=state.group;$('crumbPage').textContent=state.detail?state.detail.title:state.page}
