    function simpleTable(headers,rows){return '<div class="table-wrap"><table class="table" style="min-width:760px"><thead><tr>'+headers.map(function(header){return '<th>'+esc(header)+'</th>'}).join('')+'</tr></thead><tbody>'+rows.map(function(row){return '<tr>'+row.map(function(value){return '<td>'+value+'</td>'}).join('')+'</tr>'}).join('')+'</tbody></table></div>'}
    function stationGunTotal(station){return Number(station.ultra||0)+Number(station.fast||0)+Number(station.slow||0)}
