    function stationMarkup(station){var plan=plans.find(function(item){return item.name===station.plan}),current=plan?plan.periods[2]:defaultPeriods[2];return '<article class="station-card"><header class="station-head"><div style="min-width:0"><div class="station-name" title="'+esc(station.name)+'">'+esc(station.name)+'</div><div class="station-meta">'+esc(station.id)+' · '+esc(station.operator)+'</div></div>'+actionButton('station',station.id)+'</header><div class="station-types"><span class="station-type-pill">'+esc(station.type)+'</span><span class="station-type-pill secondary">'+esc(station.facility)+'</span></div><div class="station-card-kpis"><div class="station-card-kpi"><label>运行状态</label><div>'+badge(station.status)+'</div></div><div class="station-card-kpi"><label>通讯状态</label><div>'+badge(communicationLabel(station.communication))+'</div></div><div class="station-card-kpi"><label>设备规模</label><div>'+station.piles+' 桩 / '+stationGunTotal(station)+' 枪</div></div><div class="station-card-kpi"><label>当前价格</label><div>'+money(current.electricity+current.service)+' 元/kWh</div></div></div><div class="station-card-body"><div class="station-card-line"><span>地址</span><div title="'+esc(station.address)+'">'+esc(station.address)+'</div></div><div class="station-card-line"><span>营业</span><div>'+esc(station.hours)+'</div></div></div></article>'}
    function stationOverview(){var totalGuns=stations.reduce(function(sum,item){return sum+stationGunTotal(item)},0),charging=stations.reduce(function(sum,item){return sum+item.charging},0),fault=stations.reduce(function(sum,item){return sum+item.fault},0),offline=stations.reduce(function(sum,item){return sum+item.offline},0),idle=Math.max(0,totalGuns-charging-fault-offline),statusItems=[['全部场站',stations.length,'primary'],['正常运营',stations.filter(function(item){return item.status==='正常'}).length,''],['维护中',stations.filter(function(item){return item.status==='维护中'}).length,''],['建设中',stations.filter(function(item){return item.status==='建设中'}).length,''],['已下线',stations.filter(function(item){return item.status==='下线'}).length,'']],communicationItems=[['通讯正常',stations.filter(function(item){return item.communication==='正常'}).length,'#299361'],['部分中断',stations.filter(function(item){return item.communication==='异常'}).length,'#d2933f'],['通讯异常',stations.filter(function(item){return item.communication==='未接入'}).length,'#c95b59']];return '<div class="station-overview"><section class="station-summary-card"><div class="summary-heading"><strong>场站运行概况</strong><span>按场站维度统计</span></div><div class="station-state-grid">'+statusItems.map(function(item){return '<div class="station-state-item '+item[2]+'"><span>'+item[0]+'</span><strong>'+item[1]+'</strong></div>'}).join('')+'</div></section><section class="station-summary-card"><div class="summary-heading"><strong>场站通讯状态</strong></div><div class="communication-grid">'+communicationItems.map(function(item){return '<div class="communication-item"><strong style="color:'+item[2]+'">'+item[1]+'</strong><span>'+item[0]+'</span></div>'}).join('')+'</div></section></div><div class="device-strip"><div class="device-strip-title"><strong>设备状态</strong><span>按充电枪维度统计</span></div><div class="device-stat"><strong>'+stations.reduce(function(sum,item){return sum+item.piles},0)+'</strong><span>充电桩</span></div><div class="device-stat"><strong>'+totalGuns+'</strong><span>充电枪</span></div><div class="device-stat"><strong style="color:#3c6cef">'+charging+'</strong><span>充电中</span></div><div class="device-stat"><strong style="color:#299361">'+idle+'</strong><span>空闲</span></div><div class="device-stat"><strong style="color:#d45353">'+fault+'</strong><span>故障</span></div><div class="device-stat"><strong style="color:#7e8796">'+offline+'</strong><span>离线</span></div></div>'}
    function stationCell(item,key){if(key==='id')return '<td class="code">'+item.id+'</td>';if(key==='name')return '<td>'+esc(item.name)+'</td>';if(key==='status')return '<td>'+badge(item.status)+'</td>';if(key==='communication')return '<td>'+badge(communicationLabel(item.communication))+'</td>';if(key==='equipment')return '<td class="equipment-cell"><strong>'+item.piles+' 桩 / '+stationGunTotal(item)+' 枪</strong><span>超快 '+Number(item.ultra||0)+' · 快 '+Number(item.fast||0)+' · 慢 '+Number(item.slow||0)+'</span></td>';if(key==='electricShare'||key==='serviceShare')return '<td>'+item[key]+'%</td>';return '<td>'+esc(item[key])+'</td>'}
    function renderStationTable(records){var defs=state.stationColumns.map(function(key){return stationFieldDefs.find(function(item){return item.key===key})}).filter(function(item){return item&&state.stationHidden.indexOf(item.key)===-1});return renderTable(defs.map(function(item){return item.label}),records,function(item){return '<tr>'+defs.map(function(def){return stationCell(item,def.key)}).join('')+'<td class="actions">'+actionButton('station',item.id)+'</td></tr>'})}
    function stationColumnSettings(){var rows=state.stationColumns.map(function(key){var def=stationFieldDefs.find(function(item){return item.key===key}),checked=state.stationHidden.indexOf(key)===-1;return '<div class="column-row" draggable="true" data-column-row data-key="'+key+'"><span class="column-grip" title="拖动排序">⠿</span><label class="column-check"><input type="checkbox" data-column-visible '+(checked?'checked':'')+' '+(def.required?'disabled':'')+'><span>'+esc(def.label)+(def.required?'（不可取消）':'')+'</span></label><div class="column-order"><button data-action="column-up" aria-label="上移">↑</button><button data-action="column-down" aria-label="下移">↓</button></div></div>'}).join('');openModal('字段设置','<div class="column-tip">勾选控制字段展示；拖动字段，或使用上下箭头调整列表顺序。</div><div class="column-settings" id="columnSettings">'+rows+'</div>',[{label:'保存设置',action:'save-station-columns',primary:true}])}
    function renderStations(){var records=stations.filter(match),actions='<button class="btn btn-primary" data-action="drawer" data-kind="station">＋ 新增场站</button><div class="view-switch"><button class="view-btn '+(state.stationView==='cards'?'active':'')+'" data-action="station-view" data-view="cards">▦ 卡片</button><button class="view-btn '+(state.stationView==='list'?'active':'')+'" data-action="station-view" data-view="list">☷ 列表</button></div>'+(state.stationView==='list'?'<button class="btn" data-action="station-columns">字段设置</button>':'')+'<button class="btn" data-action="export">导出 Excel</button>',body;if(state.stationView==='cards')body='<div class="station-cards">'+rowsPage(records).map(stationMarkup).join('')+'</div>'+pagination(records.length);else body=renderStationTable(records);$('content').innerHTML=stationOverview()+'<section class="surface"><div class="station-commandbar">'+querybar('搜索站点编号、站点名称、地址')+'<div class="toolbar-actions">'+actions+'</div></div><div class="station-list-heading">场站列表<span>共 '+records.length+' 条</span></div>'+body+'</section>'}
    function planAppliedStations(plan){return stations.filter(function(station){return station.plan===plan.name})}
    function planPriceRange(plan,field){var values=plan.periods.map(function(period){return Number(period[field]||0)}),min=Math.min.apply(null,values),max=Math.max.apply(null,values);return money(min)+(min===max?'':' - '+money(max))}
    function pricingMatch(record){var query=state.keyword.trim().toLowerCase(),linkedStation=record.stationId?stationById(record.stationId):null,searchable=JSON.stringify(record)+(linkedStation?linkedStation.name+linkedStation.operator:'');if(query&&searchable.toLowerCase().indexOf(query)===-1)return false;return Object.keys(state.filters).every(function(key){var expected=state.filters[key];if(!expected)return true;if(key==='station'){if(record.id&&record.id.indexOf('JF')===0)return planAppliedStations(record).some(function(station){return station.id===expected});return record.stationId===expected}if(key==='operator'){var operator=record.operator||(linkedStation?linkedStation.operator:'');return operator===expected}return String(record[key]||'')===expected})}
    function pricingTabs(){return '<div class="tabs pricing-tabs"><button class="tab '+(state.pricingTab==='收费方案'?'active':'')+'" data-action="pricing-tab" data-tab="收费方案">收费方案</button><button class="tab '+(state.pricingTab==='预约调价'?'active':'')+'" data-action="pricing-tab" data-tab="预约调价">预约调价</button><span class="pricing-tab-note">先维护收费方案，再按场站预约生效</span></div>'}
    function plansPanel(){var records=plans.filter(pricingMatch),actions='<button class="btn btn-primary" data-action="drawer" data-kind="plan">＋ 新增收费方案</button><button class="btn" data-action="export">导出 Excel</button>';return querybar('搜索方案名称、方案编号')+toolbar('收费方案',records.length,actions)+renderTable(['方案编号','收费方案','所属运营商','收费时段','电费区间 (元/kWh)','服务费区间 (元/kWh)','应用场站','方案状态','更新时间'],records,function(item){var applied=planAppliedStations(item);return '<tr><td class="code">'+item.id+'</td><td>'+esc(item.name)+'</td><td>'+esc(item.operator)+'</td><td>'+item.periods.length+' 组时段</td><td class="price-range">'+planPriceRange(item,'electricity')+'</td><td class="price-range">'+planPriceRange(item,'service')+'</td><td><button class="btn-link" data-action="related-stations" data-id="'+item.id+'">'+applied.length+' 个场站</button></td><td>'+badge(item.status)+'</td><td>'+item.updated+'</td><td class="actions">'+actionButton('plan',item.id)+'</td></tr>'})}
    function schedulesPanel(){var records=schedules.filter(pricingMatch),actions='<button class="btn btn-primary" data-action="drawer" data-kind="schedule">＋ 新增预约调价</button><button class="btn" data-action="export">导出 Excel</button>';return querybar('搜索任务名称、关联场站')+toolbar('预约调价',records.length,actions)+renderTable(['任务编号','调价任务','所属场站','目标收费方案','预约生效时间','预约结束时间','到期处理','执行状态'],records,function(item){var station=stationById(item.stationId);return '<tr><td class="code">'+item.id+'</td><td>'+esc(item.name)+'</td><td>'+esc(station?station.name:'—')+'</td><td>'+esc(item.plan)+'</td><td>'+item.start+'</td><td>'+item.end+'</td><td>'+(item.restore?'自动恢复原方案':'保持新方案')+'</td><td>'+badge(item.status)+'</td><td class="actions">'+actionButton('schedule',item.id)+'</td></tr>'})}
    function renderPricing(){$('content').innerHTML='<section class="surface">'+pricingTabs()+(state.pricingTab==='收费方案'?plansPanel():schedulesPanel())+'</section>'}
    function renderPiles(){var records=piles.filter(match),actions='<button class="btn btn-primary" data-action="drawer" data-kind="pile">＋ 新增充电桩</button><button class="btn" data-action="batch-qr">批量导出二维码</button><button class="btn" data-action="export">导出 Excel</button>';$('content').innerHTML=metrics([{label:'充电桩总数',value:piles.length,icon:'▥'},{label:'在线',value:piles.filter(function(item){return item.status==='在线'}).length,icon:'●'},{label:'离线',value:piles.filter(function(item){return item.status==='离线'}).length,icon:'○',className:'metric-warning'},{label:'未激活',value:piles.filter(function(item){return item.status==='未激活'}).length,icon:'◌'}])+'<section class="surface">'+querybar('搜索设备编码、充电桩名称')+toolbar('充电桩列表',records.length,actions)+renderTable(['设备编码','充电桩名称','所属场站','所属运营商','设备厂商','直流 / 交流','枪数量','功率 (kW)','设备状态','启用状态','二维码','创建时间'],records,function(item){var station=stationById(item.stationId);return '<tr><td class="code">'+item.id+'</td><td>'+esc(item.name)+'</td><td>'+esc(station?station.name:'未绑定')+'</td><td>'+esc(item.operator)+'</td><td>'+esc(item.brand)+'</td><td>'+esc(item.type)+'</td><td>'+item.gunCount+'</td><td>'+item.power+'</td><td>'+badge(item.status)+'</td><td>'+badge(item.enabled?'启用':'停用')+'</td><td><button class="btn-link" data-action="qr" data-id="'+item.id+'">查看二维码</button></td><td>'+item.created+'</td><td class="actions">'+actionButton('pile',item.id)+'</td></tr>'})+'</section>'}
    function renderGuns(){var records=guns.filter(match),actions='<button class="btn btn-primary" data-action="drawer" data-kind="gun">＋ 新增充电枪</button><button class="btn" data-action="export">导出 Excel</button>';$('content').innerHTML=metrics([{label:'充电枪总数',value:guns.length,icon:'ϟ'},{label:'充电中',value:guns.filter(function(item){return item.status==='充电中'}).length,icon:'●'},{label:'空闲',value:guns.filter(function(item){return item.status==='空闲'}).length,icon:'○'},{label:'故障',value:guns.filter(function(item){return item.status==='故障'}).length,icon:'△',className:'metric-danger'}])+'<section class="surface">'+querybar('搜索枪编号、充电桩编码')+toolbar('充电枪列表',records.length,actions)+renderTable(['枪编号','所属场站','所属充电桩','所属运营商','枪类型','枪状态','电压 (V)','电流 (A)','SOC (%)','枪线温度 (℃)','电池温度 (℃)','充电时间 (分钟)','剩余时间 (分钟)','故障状态'],records,function(item){var station=stationById(item.stationId);return '<tr><td class="code">'+item.id+'</td><td>'+esc(station?station.name:'—')+'</td><td class="code">'+item.pileId+'</td><td>'+esc(item.operator)+'</td><td>'+esc(item.type)+'</td><td>'+badge(item.status)+'</td><td>'+item.voltage+'</td><td>'+item.current+'</td><td>'+item.soc+'</td><td>'+item.cableTemp+'</td><td>'+item.batteryTemp+'</td><td>'+item.chargeMinutes+'</td><td>'+item.remaining+'</td><td>'+badge(item.fault)+'</td><td class="actions">'+actionButton('gun',item.id)+'</td></tr>'})+'</section>'}
    function renderLogs(){var records=logs.filter(match),actions='<button class="btn" data-action="export">导出 Excel</button>';$('content').innerHTML='<section class="surface">'+querybar('搜索日志编号、设备编码、命令类型')+toolbar('充电桩日志',records.length,actions)+renderTable(['日志编号','设备编码','命令类型','请求数据','请求报文','日志时间','发送状态'],records,function(item){return '<tr><td class="code">'+item.id+'</td><td class="code">'+item.pileId+'</td><td>'+esc(item.type)+'</td><td class="code">'+esc(item.request)+'</td><td class="code">'+esc(item.message)+'</td><td>'+item.time+'</td><td>'+badge(item.status)+'</td><td class="actions">'+actionButton('log',item.id)+'</td></tr>'})+'</section>'}
    function renderCampaigns(){var records=campaigns.filter(match),cards='<div class="templates">'+templates.map(function(item){return '<button class="template-card" data-action="campaign-template" data-template="'+esc(item.name)+'"><i class="template-icon">'+item.icon+'</i><strong>'+esc(item.name)+'</strong><span>'+esc(item.hint)+'</span></button>'}).join('')+'</div>',actions='<button class="btn btn-primary" data-action="drawer" data-kind="campaign">＋ 新建活动</button><button class="btn" data-action="export">导出 Excel</button>';$('content').innerHTML=cards+'<section class="surface">'+querybar('搜索活动名称、活动编号')+toolbar('活动投放',records.length,actions)+renderTable(['活动名称','活动标题','活动模板','优惠范围','参与场站','活动对象','活动时间','预算 / 已用 (元)','参与人数','活动状态'],records,function(item){return '<tr><td>'+esc(item.name)+'<span class="subtext">'+item.id+'</span></td><td>'+esc(item.title)+'</td><td>'+pill(item.template,'tag-blue')+'</td><td>'+esc(item.fee)+'</td><td>'+item.stations.length+' 个场站</td><td>'+esc(item.audience)+'</td><td>'+item.start+' 至 '+item.end+'</td><td>'+money(item.budget)+' / '+money(item.used)+'</td><td>'+item.people+'</td><td>'+badge(item.status)+'</td><td class="actions">'+actionButton('campaign',item.id)+'</td></tr>'})+'</section>'}
    function renderCoupons(){var records=coupons.filter(match),actions='<button class="btn btn-primary" data-action="drawer" data-kind="coupon">＋ 新建优惠券</button><button class="btn" data-action="export">导出 Excel</button>';$('content').innerHTML=metrics([{label:'优惠券模板',value:coupons.length,icon:'◈'},{label:'已发放',value:coupons.reduce(function(sum,item){return sum+item.issued},0),icon:'↗'},{label:'已核销',value:coupons.reduce(function(sum,item){return sum+item.used},0),icon:'✓'},{label:'待核销',value:coupons.reduce(function(sum,item){return sum+item.issued-item.used},0),icon:'◷'}])+'<section class="surface">'+querybar('搜索优惠券名称、券编号')+toolbar('优惠券管理',records.length,actions)+renderTable(['券编号','优惠券名称','券类型','优惠费用','使用门槛','优惠金额','发行总量','已发放','已使用','截止日期','状态'],records,function(item){return '<tr><td class="code">'+item.id+'</td><td>'+esc(item.name)+'</td><td>'+esc(item.type)+'</td><td>'+esc(item.fee)+'</td><td>'+item.threshold+'</td><td>'+esc(item.value)+'</td><td>'+item.inventory+'</td><td>'+item.issued+'</td><td>'+item.used+'</td><td>'+item.end+'</td><td>'+badge(item.status)+'</td><td class="actions">'+actionButton('coupon',item.id)+'</td></tr>'})+'</section>'}
