    function renderOrders(){var records=orders.filter(match),actions='<button class="btn" data-action="show-abnormal">仅看异常订单</button><button class="btn" data-action="export">导出 Excel</button>';$('content').innerHTML=metrics([{label:'充电订单',value:orders.length,icon:'▧'},{label:'充电中',value:orders.filter(function(item){return item.status==='充电中'}).length,icon:'ϟ'},{label:'异常订单',value:orders.filter(function(item){return item.abnormal}).length,icon:'△',className:'metric-danger'},{label:'退费处理中',value:orders.filter(function(item){return item.refundStatus==='待审批'}).length,icon:'↶',className:'metric-warning'}])+'<section class="surface">'+querybar('搜索订单编号、手机号、设备编码')+toolbar('充电订单',records.length,actions)+renderTable(['订单编号','所属场站','用户 / 车牌','充电量 (kWh)','电费 (元)','服务费 (元)','优惠 (元)','用户实付 (元)','设备上报 (元)','金额差异 (元)','支付方式','订单状态','退款状态','订单时间'],records,function(item){var station=stationById(item.stationId),user=userById(item.userId),difference=orderDifference(item);return '<tr><td class="code">'+item.id+(item.abnormal?'<span class="subtext difference">异常订单</span>':'')+'</td><td>'+esc(station?station.name:'—')+'</td><td>'+esc(user?user.phone:'—')+'<span class="subtext">'+esc(item.plate)+'</span></td><td>'+item.quantity+'</td><td>'+money(item.electricity)+'</td><td>'+money(item.service)+'</td><td>'+money(item.discount)+'</td><td>'+money(item.paid)+'</td><td>'+money(item.deviceAmount)+'</td><td class="'+(difference?'difference':'')+'">'+money(difference)+'</td><td>'+esc(item.payment)+'</td><td>'+badge(item.status)+'</td><td>'+badge(item.refundStatus)+'</td><td>'+item.created+'</td><td class="actions">'+actionButton('order',item.id)+'</td></tr>'})+'</section>'}
