    function renderEnterprises(){var records=enterprises.filter(match),actions='<button class="btn btn-primary" data-action="drawer" data-kind="enterprise">＋ 新增企业</button><button class="btn" data-action="export">导出 Excel</button>';$('content').innerHTML=metrics([{label:'合作企业',value:enterprises.length,icon:'▦'},{label:'企业预付余额',value:money(enterprises.reduce(function(sum,item){return sum+item.balance},0)),unit:'元',icon:'¥'},{label:'企业车辆',value:enterprises.reduce(function(sum,item){return sum+item.vehicles},0),icon:'◈'},{label:'余额预警',value:enterprises.filter(function(item){return item.balance<item.threshold}).length,icon:'△',className:'metric-warning'}])+'<section class="surface">'+querybar('搜索企业名称、联系人')+toolbar('企业管理',records.length,actions)+renderTable(['企业编号','企业名称','联系人','联系电话','预付余额 (元)','预警阈值 (元)','单次额度 (元)','企业车辆','账户状态','创建时间'],records,function(item){return '<tr><td class="code">'+item.id+'</td><td>'+esc(item.name)+'</td><td>'+esc(item.contact)+'</td><td>'+esc(item.phone)+'</td><td class="'+(item.balance<item.threshold?'difference':'')+'">'+money(item.balance)+'</td><td>'+money(item.threshold)+'</td><td>'+money(item.limit)+'</td><td>'+item.vehicles+'</td><td>'+badge(item.status)+'</td><td>'+item.created+'</td><td class="actions">'+actionButton('enterprise',item.id)+'</td></tr>'})+'</section>'}
