    function pileMatchV2(item){var query=String(state.keyword||'').trim().toLowerCase(),station=stationById(item.stationId),searchable=[item.id,item.name,item.brand,item.operator,station?station.name:''].join(' ').toLowerCase();if(query&&searchable.indexOf(query)===-1)return false;return Object.keys(state.filters||{}).every(function(key){var expected=state.filters[key];if(!expected)return true;if(key==='station')return item.stationId===expected;if(key==='gunCount')return Number(item.gunCount)===Number(expected);if(key==='powerMin')return Number(item.power)>=Number(expected);if(key==='powerMax')return Number(item.power)<=Number(expected);if(key==='enabled')return expected==='enabled'?!!item.enabled:!item.enabled;return String(item[key]||'')===String(expected)})}
