    var filterConfigV25Base=filterConfig;filterConfig=function(){if(state.page==='用户管理'&&state.userManagementTab==='用户分组')return [{key:'type',label:'分组方式',options:['动态规则','手动名单'],placeholder:'全部分组方式'},{key:'status',label:'状态',options:['启用','停用'],placeholder:'全部状态'}];if(state.page==='用户管理'&&state.userManagementTab==='免费用户')return [{key:'dimension',label:'适用维度',options:[{value:'operator',label:'运营商维度'},{value:'station',label:'场站维度'}],placeholder:'全部适用维度'},{key:'status',label:'状态',options:['启用','停用','即将用尽'],placeholder:'全部状态'}];if(state.page==='充值订单')return [{key:'balanceState',label:'余额状态',options:['未使用','部分使用','已用完'],placeholder:'全部余额状态'},{key:'refundStatus',label:'退款状态',options:['无退款','退款处理中','已退款'],placeholder:'全部退款状态'},{key:'created',label:'充值时间',type:'dateRange'}];if(state.page==='充值管理')return [{key:'status',label:'启用状态',options:['启用','停用'],placeholder:'全部状态'}];return filterConfigV25Base()};
    function renderUserGroupsV25(){var records=userGroups.filter(match),actions='<button class="btn btn-primary" data-action="user-group-new">＋ 新建用户分组</button><button class="btn" data-action="export">导出 Excel</button>';$('content').innerHTML='<div class="group-summary"><article><span>用户分组</span><strong>'+userGroups.length+'</strong></article><article><span>动态规则分组</span><strong>'+userGroups.filter(function(item){return item.type==='动态规则'}).length+'</strong></article><article><span>手动名单</span><strong>'+userGroups.filter(function(item){return item.type==='手动名单'}).length+'</strong></article></div><section class="surface">'+userManagementTabsV5('用户分组')+querybar('请输入用户组名称')+toolbar('用户分组',records.length,actions)+renderTable(['分组编号','分组名称','分组方式','分组规则','预计人数','状态','更新时间'],records,function(item){return '<tr><td class="code">'+item.id+'</td><td><strong>'+esc(item.name)+'</strong></td><td>'+pill(item.type,item.type==='动态规则'?'tag-blue':'')+'</td><td><div class="group-rule-cell"><strong>'+esc(item.rule)+'</strong><span>'+(item.type==='动态规则'?'每 10 分钟自动更新人群快照':'按已保存的手动名单维护')+'</span></div></td><td><button class="campaign-list-link" data-action="user-group-members" data-id="'+item.id+'">'+item.estimated.toLocaleString('zh-CN')+' 人</button></td><td>'+badge(item.status)+'</td><td>'+item.updated+'</td><td class="actions"><button class="more" data-action="user-group-edit" data-id="'+item.id+'">···</button></td></tr>'})+'</section>'}
