    function renderFreeUsersV25(){freeUsers.forEach(function(item){var user=userById(item.userId);item.userName=user?user.nickname:'';item.phone=user?user.phone:''});var records=freeUsers.filter(match),actions='<button class="btn btn-primary" data-action="drawer" data-kind="free-user">＋ 维护免费用户</button><button class="btn" data-action="export">导出 Excel</button>';$('content').innerHTML=metrics([{label:'免费用户',value:freeUsers.length,icon:'♙'},{label:'启用中',value:freeUsers.filter(function(item){return item.status==='启用'}).length,icon:'✓'},{label:'运营商范围',value:freeUsers.filter(function(item){return item.dimension==='operator'}).length,icon:'▦'},{label:'场站范围',value:freeUsers.filter(function(item){return item.dimension==='station'}).length,icon:'▤'}])+'<section class="surface">'+userManagementTabsV5('免费用户')+querybar('请输入用户昵称或手机号')+toolbar('免费用户',records.length,actions)+renderTable(['用户手机号','用户昵称','免费范围','免费额度','适用维度','适用范围','已使用','有效期','状态'],records,function(item){var user=userById(item.userId),target=freeTargetLabelV23(item);return '<tr><td>'+esc(user?user.phone:'—')+'</td><td><strong>'+esc(user?user.nickname:'—')+'</strong></td><td>'+esc(item.scope)+'</td><td>'+money(item.quotaValue)+' '+esc(item.quotaUnit)+'</td><td>'+pill(item.dimension==='operator'?'运营商维度':'场站维度','tag-blue')+'</td><td><button class="btn-link" data-action="free-target-view-v23" data-id="'+item.id+'">'+esc(target.title)+'</button></td><td>'+esc(item.used)+'</td><td>'+item.start+' 至 '+item.end+'</td><td>'+badge(item.status)+'</td><td class="actions">'+actionButton('free-user',item.id)+'</td></tr>'})+'</section>'}
    var renderUsersV25Base=renderUsers;renderUsers=function(){if(state.userManagementTab==='免费用户')renderFreeUsersV25();else renderUsersV25Base()};
    function rechargePackageByIdV25(id){return rechargePackagesV25.find(function(item){return item.id===id})}
    function rechargeOrderByIdV25(id){return rechargeOrdersV25.find(function(item){return item.id===id})}
    function rechargeRefundableV25(item){var usedPrincipal=Math.min(Number(item.payAmount||0),Number(item.usedAmount||0)),refunded=Number(item.refundAmount||0);return Number(Math.max(0,Number(item.payAmount||0)-usedPrincipal-refunded).toFixed(2))}
    function renderRechargePackagesV25(){var records=rechargePackagesV25.filter(match),actions='<button class="btn btn-primary" data-action="recharge-package-new-v25">＋ 新建充值套餐</button><button class="btn" data-action="export">导出 Excel</button>';$('content').innerHTML=metrics([{label:'充值套餐',value:records.length,icon:'¥'},{label:'启用中',value:records.filter(function(item){return item.status==='启用'}).length,icon:'✓'},{label:'累计参与',value:records.reduce(function(sum,item){return sum+item.sold},0),unit:'人次',icon:'♙'},{label:'累计赠送',value:money(records.reduce(function(sum,item){return sum+item.giftAmount*item.sold},0)),unit:'元',icon:'◇'}])+'<section class="surface">'+querybar('请输入套餐名称或套餐编号')+toolbar('充值管理',records.length,actions)+renderTable(['套餐编号','套餐名称','充值金额 (元)','赠送金额 (元)','到账金额 (元)','有效期','参与人次','启用状态','更新时间'],records,function(item){return '<tr><td class="code">'+item.id+'</td><td><strong>'+esc(item.name)+'</strong></td><td>'+money(item.payAmount)+'</td><td>'+money(item.giftAmount)+'</td><td><strong>'+money(item.totalAmount)+'</strong></td><td>'+esc(item.effective)+'</td><td>'+item.sold.toLocaleString('zh-CN')+'</td><td><div class="package-status-v25"><button class="user-status-switch '+(item.status==='启用'?'active':'')+'" data-action="recharge-package-toggle-v25" data-id="'+item.id+'" aria-label="'+(item.status==='启用'?'停用':'启用')+'套餐"></button></div></td><td>'+item.updated+'</td><td class="actions"><button class="more" data-action="recharge-package-edit-v25" data-id="'+item.id+'">···</button></td></tr>'})+'</section>'}
